sp_widget.client_script:
api.controller = function($scope) {

  /* =========================================================
     GATENOW · APPLICATION STATUS · Client script

     Filter, paginate, expand. Nothing here writes to
     window.location or calls window.open, so there is no
     navigation sink for the open-redirect scan to find — the
     attachment link is an anchor in the template built from a
     validated sys_id.

     The matched list is cached. It is read by the template, by
     the pager and by the range text, so without a cache Angular
     re-filters the whole array several times per digest and
     hands ng-repeat a fresh array reference each time, which
     stops the list ever settling.
     ========================================================= */

  var c = this;

  c.query    = '';
  c.filter   = 'all';
  c.page     = 1;
  c.expanded = null;
  c.timeline = [];

  c.modalOpen = false;
  c.selected  = {};
  c.tab       = 'personal';

  var SIZE = c.data.pageSize || 10;


  /* =====================================================
     MATCHING
     ===================================================== */

  var lastKey  = null;
  var lastList = [];

  c.matches = function() {

    var all = c.data.applications || [];
    var key = all.length + '|' + c.filter + '|' + (c.query || '').toLowerCase();

    if (key === lastKey) return lastList;

    var list = all;

    if (c.filter !== 'all') {
      list = list.filter(function(a) { return a.tone === c.filter; });
    }

    var q = (c.query || '').trim().toLowerCase();
    if (q) {
      /* the searchable blob is assembled server-side, so this is
         one indexOf per row rather than four joins per keystroke */
      list = list.filter(function(a) { return a.search.indexOf(q) > -1; });
    }

    lastKey  = key;
    lastList = list;
    return list;
  };


  /* =====================================================
     PAGING

     Ten to a page. The slice is cached on the same key as the
     matched list plus the page number, for the same reason.
     ===================================================== */

  var pageKey  = null;
  var pageList = [];

  c.pageCount = function() {
    return Math.max(1, Math.ceil(c.matches().length / SIZE));
  };

  c.pageRows = function() {

    var rows = c.matches();
    var key  = lastKey + '|' + c.page;

    if (key === pageKey) return pageList;

    var start = (c.page - 1) * SIZE;
    pageList = rows.slice(start, start + SIZE);
    pageKey  = key;
    return pageList;
  };

  /* A window of page numbers rather than all of them. Thirty
     applications is three pages and fits; three hundred is
     thirty buttons and does not, so the middle collapses to an
     ellipsis and the first, last and current always show. */
  c.pageList = function() {

    var total = c.pageCount();
    var out   = [];

    if (total <= 7) {
      for (var i = 1; i <= total; i++) out.push(i);
      return out;
    }

    out.push(1);

    var from = Math.max(2, c.page - 1);
    var to   = Math.min(total - 1, c.page + 1);

    if (from > 2) out.push('…');
    for (var p = from; p <= to; p++) out.push(p);
    if (to < total - 1) out.push('…');

    out.push(total);
    return out;
  };

  c.go = function(p) {
    if (p === '…') return;
    var total = c.pageCount();
    if (p < 1 || p > total || p === c.page) return;
    c.page = p;
    /* a row expanded on the page being left should not reappear
       expanded on the page being entered */
    c.expanded = null;
  };

  c.rangeText = function() {
    var n = c.matches().length;
    if (!n) return '';
    var from = (c.page - 1) * SIZE + 1;
    var to   = Math.min(n, c.page * SIZE);
    return c.data.t.showing + ' ' + from + '–' + to + ' ' + c.data.t.of + ' ' + n;
  };


  /* =====================================================
     FILTERS
     ===================================================== */

  function countTone(tone) {
    var all = c.data.applications || [];
    if (tone === 'all') return all.length;
    return all.filter(function(a) { return a.tone === tone; }).length;
  }

  c.filters = [
    { key: 'all',      label: c.data.t.fAll,      count: function() { return countTone('all'); } },
    { key: 'pending',  label: c.data.t.fPending,  count: function() { return countTone('pending'); } },
    { key: 'active',   label: c.data.t.fActive,   count: function() { return countTone('active'); } },
    { key: 'done',     label: c.data.t.fDone,     count: function() { return countTone('done'); } },
    { key: 'declined', label: c.data.t.fDeclined, count: function() { return countTone('declined'); } }
  ];

  /* any change to what is matched sends the reader back to page
     one — staying on page four of a result set that now has one
     page shows an empty list */
  c.onFilterChange = function() {
    lastKey  = null;
    pageKey  = null;
    c.page   = 1;
    c.expanded = null;
  };

  c.setFilter = function(key) {
    if (c.filter === key) return;
    c.filter = key;
    c.onFilterChange();
  };

  c.clearSearch = function() {
    c.query = '';
    c.onFilterChange();
  };

  c.reset = function() {
    c.query  = '';
    c.filter = 'all';
    c.onFilterChange();
  };


  /* =====================================================
     THE TIMELINE
     ===================================================== */

  c.toggle = function(app) {

    if (c.expanded === app.sys_id) {
      c.expanded = null;
      c.timeline = [];
      return;
    }

    c.expanded = app.sys_id;
    c.timeline = (c.data.timelines && c.data.timelines[app.sys_id]) || [];
  };


  /* =====================================================
     THE DETAIL PANEL
     ===================================================== */

  c.modalTabs = [
    { key: 'personal', label: c.data.t.tabPersonal },
    { key: 'identity', label: c.data.t.tabIdentity },
    { key: 'program',  label: c.data.t.tabProgram },
    { key: 'files',    label: c.data.t.tabFiles }
  ];

  c.setTab = function(key) { c.tab = key; };

  c.openModal = function(app) {
    c.selected  = app;
    c.tab       = 'personal';
    c.modalOpen = true;
    document.body.style.overflow = 'hidden';
  };

  c.closeModal = function() {
    c.modalOpen = false;
    c.selected  = {};
    document.body.style.overflow = '';
  };


  /* =====================================================
     ATTACHMENTS
     ===================================================== */

  /* Returns a link for the template, or an empty string when the
     reference is not a real sys_id — 32 lowercase hex characters
     and nothing else. Empty rather than null: ng-href on an
     empty value renders nothing usable, whereas the string
     "null" would render a link to a page that does not exist. */
  c.fileHref = function(sysId) {
    return /^[0-9a-f]{32}$/.test(sysId || '')
      ? '/sys_attachment.do?sys_id=' + encodeURIComponent(sysId)
      : '';
  };

  c.fileSize = function(bytes) {
    var b = parseInt(bytes, 10);
    if (!b || isNaN(b)) return '0 B';
    if (b < 1024)    return b + ' B';
    if (b < 1048576) return (b / 1024).toFixed(1) + ' KB';
    return (b / 1048576).toFixed(1) + ' MB';
  };

  c.fileIcon = function(type) {
    var t = (type || '').toLowerCase();
    if (t.indexOf('pdf')   > -1) return 'fa-file-pdf-o';
    if (t.indexOf('image') > -1) return 'fa-file-image-o';
    if (t.indexOf('word')  > -1) return 'fa-file-word-o';
    if (t.indexOf('excel') > -1 || t.indexOf('sheet') > -1) return 'fa-file-excel-o';
    if (t.indexOf('zip')   > -1) return 'fa-file-archive-o';
    return 'fa-file-o';
  };


  /* =====================================================
     ESCAPE CLOSES WHAT IS OPEN

     The listener is removed on destroy. The previous version
     added one to document on every instantiation and never took
     it off, so moving around the portal left a stack of
     handlers all calling $apply on dead scopes.
     ===================================================== */

  function onKey(e) {
    if (e.key !== 'Escape' && e.keyCode !== 27) return;
    if (!c.modalOpen && c.expanded === null) return;

    $scope.$apply(function() {
      if (c.modalOpen) c.closeModal();
      else c.expanded = null;
    });
  }

  document.addEventListener('keydown', onKey);

  $scope.$on('$destroy', function() {
    document.removeEventListener('keydown', onKey);
    /* torn down with the panel open, the body would stay locked
       and the page unscrollable */
    document.body.style.overflow = '';
  });
};

sp_widget.css:
/* =========================================================
   GATENOW · APPLICATION STATUS
   Service Portal widget · CSS / SCSS

   Selectors are written out in full. The Service Portal Sass
   compiler does not support parent selector concatenation.

   A standalone page, not a dashboard. No rail, no chrome — one
   centred column at 1120px whose only job is to let somebody
   find their application and see where it has got to.

   COLOUR
   Four tones, not eleven. A colour here names a kind of state:
   amber is waiting on somebody, blue is moving, green is
   finished, grey is stopped. The state's own label carries the
   detail — eleven hues carried nothing, because nobody
   memorises eleven hues.

   TYPE — the GateNow scale, unchanged
     figure    34  700  tabular   the summary total
     title     26  700  -0.03em   page title
     section   19  600  -0.018em  card headings
     body      15  400            supporting copy
     data      14  600  tabular   dates and values
     label     11  600   0.14em   uppercase small caps
   ========================================================= */

/* ---------- typeface ---------- */

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 400;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_regular.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 500;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_medium.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 600;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_semibold.woff2") format("woff2");
}

@font-face {
  font-family: "Outfit";
  font-style: normal;
  font-weight: 700;
  font-display: swap;
  src: url("/x_enno_gatenow_outfit_bold.woff2") format("woff2");
}


/* ---------- ink ---------- */
$a-navy:   #0a2540;
$a-ink-2:  rgba(10, 37, 64, 0.72);
$a-ink-3:  rgba(10, 37, 64, 0.54);
$a-ink-4:  rgba(10, 37, 64, 0.38);
$a-line:   rgba(10, 37, 64, 0.10);
$a-line-2: rgba(10, 37, 64, 0.06);
$a-tint:   rgba(10, 37, 64, 0.03);

/* ---------- accent ---------- */
$a-blue:    #1560e0;
$a-blue-dk: #0f4cbb;
$a-blue-1:  rgba(21, 96, 224, 0.08);
$a-blue-2:  rgba(21, 96, 224, 0.16);

/* ---------- the four tones ---------- */
$a-good:   #1f8a63;
$a-warn:   #a4741f;
$a-warn-1: rgba(164, 116, 31, 0.10);
$a-stop:   #b8394a;
$a-stop-1: rgba(184, 57, 74, 0.08);

$a-white: #ffffff;
$a-page:  #f4f6fb;
$a-ease:  cubic-bezier(0.45, 0.05, 0.25, 1);

$a-font: "Outfit", "Segoe UI", Roboto, -apple-system, BlinkMacSystemFont, "Helvetica Neue", Arial, sans-serif;


/* =========================================================
   PAGE
   ========================================================= */

/* Service Portal wraps every widget in a panel that clips and
   pads. This page is the whole page, so the wrapper gets out of
   its way. */
.panel,
.panel-body,
.sp-widget { overflow: visible !important; }

.gas-page {
  width: 100%;
  min-height: 100vh;
  padding: 40px 24px 96px;
  background: $a-page;
  font-family: $a-font;
  color: $a-navy;
  -webkit-font-smoothing: antialiased;
}

/* one column, centred. 1120 is wide enough for the row's five
   fields without the programme name wrapping on a typical
   entry, and narrow enough that the eye does not have to travel
   across a whole monitor to get from the reference to the
   progress bar */
.gas {
  max-width: 1120px;
  margin: 0 auto;
}

.gas-page *,
.gas-page *::before,
.gas-page *::after { box-sizing: border-box; }


/* =========================================================
   HEADER
   ========================================================= */

.gas-top {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 26px;
}

.gas-back {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  height: 30px;
  padding: 0 11px 0 7px;
  margin-bottom: 4px;
  border-radius: 9px;
  background: transparent;
  color: $a-ink-3;
  font-size: 13.5px;
  font-weight: 500;
  text-decoration: none;
  transition: background 0.4s $a-ease, color 0.4s $a-ease;
}

.gas-back:hover,
.gas-back:focus {
  background: rgba(255, 255, 255, 0.72);
  color: $a-navy;
  text-decoration: none;
}

.gas-back__arrow {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border-radius: 50%;
  border: 1px solid $a-line;
  transition: transform 0.4s $a-ease, border-color 0.4s $a-ease;
}

.gas-back:hover .gas-back__arrow {
  transform: translateX(-3px);
  border-color: $a-blue-2;
}

.gas-page .gas-top__title {
  margin: 0;
  font-size: 26px;
  font-weight: 700;
  letter-spacing: -0.03em;
  color: $a-navy;
}

.gas-page .gas-top__sub {
  margin: 0;
  font-size: 15px;
  color: $a-ink-3;
}


/* =========================================================
   THE SUMMARY

   One card, not a row of them. The total is the headline, the
   four counts sit beside it, and the strip underneath says what
   shape the queue is in. A page of separate stat cards is a
   dashboard; this is a heading with numbers in it.
   ========================================================= */

.gas-sum {
  padding: 24px 26px 26px;
  margin-bottom: 22px;
  border: 1px solid $a-line;
  border-radius: 16px;
  background: $a-white;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
}

.gas-sum__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 22px 40px;
}

.gas-sum__total {
  display: flex;
  align-items: baseline;
  gap: 12px;
  min-width: 0;
}

.gas-page .gas-sum__figure {
  margin: 0;
  font-size: 34px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.036em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gas-page .gas-sum__label {
  margin: 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gas-page .gas-stats {
  display: flex;
  align-items: stretch;
  flex-wrap: wrap;
  gap: 0;
  margin: 0;
  padding: 0;
}

/* separated by a rule rather than a gap, so four numbers read
   as one group instead of four cards */
.gas-stat {
  display: flex;
  flex-direction: column;
  gap: 6px;
  padding: 2px 22px;
  border-left: 1px solid $a-line-2;
  min-width: 0;
}

.gas-stat:first-child {
  border-left: 0;
  padding-left: 0;
}

.gas-stat:last-child { padding-right: 0; }

.gas-page .gas-stat dt {
  margin: 0;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
  white-space: nowrap;
}

.gas-page .gas-stat dd {
  margin: 0;
  font-size: 20px;
  font-weight: 700;
  line-height: 1;
  letter-spacing: -0.022em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

/* the only count with a cost attached to ignoring it */
.gas-stat.is-alert dd { color: $a-warn; }


/* ---------- the distribution strip ---------- */

.gas-sum__spread {
  padding-top: 22px;
  margin-top: 22px;
  border-top: 1px solid $a-line-2;
}

.gas-spread {
  display: flex;
  height: 12px;
  border-radius: 999px;
  overflow: hidden;
  background: $a-tint;
  box-shadow: inset 0 0 0 1px $a-line-2;
}

.gas-spread__seg {
  display: block;
  height: 100%;
  transform-origin: left center;
}

.gas-spread__seg--pending  { background: rgba(164, 116, 31, 0.50); }
.gas-spread__seg--active   { background: rgba(21, 96, 224, 0.55); }
.gas-spread__seg--done     { background: rgba(31, 138, 99, 0.55); }
.gas-spread__seg--declined { background: rgba(10, 37, 64, 0.18); }

.gas-page .gas-key {
  display: flex;
  flex-wrap: wrap;
  gap: 10px 26px;
  margin: 15px 0 0;
  padding: 0;
  list-style: none;
}

.gas-key__item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.gas-key__swatch {
  width: 9px;
  height: 9px;
  border-radius: 3px;
  flex-shrink: 0;
}

.gas-key__swatch--pending  { background: rgba(164, 116, 31, 0.50); }
.gas-key__swatch--active   { background: rgba(21, 96, 224, 0.55); }
.gas-key__swatch--done     { background: rgba(31, 138, 99, 0.55); }
.gas-key__swatch--declined { background: rgba(10, 37, 64, 0.18); }

.gas-key__label {
  font-size: 12.5px;
  color: $a-ink-3;
}

.gas-key__n {
  font-size: 12.5px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}


/* =========================================================
   FILTERS
   ========================================================= */

.gas-filters {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 12px 20px;
  margin-bottom: 16px;
}

.gas-search {
  position: relative;
  display: flex;
  align-items: center;
  width: 320px;
  max-width: 100%;
  margin: 0;
}

.gas-search input {
  width: 100%;
  height: 42px;
  padding: 0 38px 0 40px;
  border: 1px solid $a-line;
  border-radius: 11px;
  background: $a-white;
  font-family: inherit;
  font-size: 14px;
  color: $a-navy;
  transition: border-color 0.4s $a-ease, box-shadow 0.4s $a-ease;
}

.gas-search input:focus {
  outline: 0;
  border-color: rgba(21, 96, 224, 0.45);
  box-shadow: 0 0 0 3px $a-blue-1;
}

.gas-search input::placeholder { color: $a-ink-4; }

.gas-search__ico {
  position: absolute;
  left: 15px;
  font-size: 13px;
  color: $a-ink-4;
  pointer-events: none;
}

.gas-search__clear {
  position: absolute;
  right: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: $a-tint;
  color: $a-ink-3;
  font-size: 10px;
  cursor: pointer;
  transition: background 0.3s $a-ease, color 0.3s $a-ease;
}

.gas-search__clear:hover {
  background: $a-line;
  color: $a-navy;
}

.gas-tabs {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 6px;
}

.gas-tab {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  height: 38px;
  padding: 0 14px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  color: $a-ink-2;
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  white-space: nowrap;
  flex-shrink: 0;
  cursor: pointer;
  transition: background 0.4s $a-ease, border-color 0.4s $a-ease, color 0.4s $a-ease;
}

.gas-tab:hover {
  background: rgba(255, 255, 255, 0.72);
  color: $a-navy;
}

.gas-tab.is-on {
  background: $a-white;
  border-color: $a-line;
  color: $a-navy;
  font-weight: 600;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.05);
}

.gas-tab__count {
  font-size: 12.5px;
  font-variant-numeric: tabular-nums;
  color: $a-ink-4;
}


/* =========================================================
   THE LIST

   A row per application, not a table. The fields are not
   comparable down a column the way a table implies — a
   programme name and a progress bar are different kinds of
   thing — and a row that expands is not something a table does
   gracefully.
   ========================================================= */

.gas-list {
  display: grid;
  gap: 12px;
  margin-bottom: 20px;
}

.gas-row {
  position: relative;
  border: 1px solid $a-line;
  border-radius: 16px;
  background: $a-white;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(10, 37, 64, 0.03);
  transition: border-color 0.4s $a-ease, box-shadow 0.4s $a-ease;
}

.gas-row:hover {
  border-color: $a-blue-2;
  box-shadow: 0 10px 26px rgba(10, 37, 64, 0.07);
}

.gas-row.is-open {
  border-color: $a-blue-2;
  box-shadow: 0 12px 30px rgba(10, 37, 64, 0.08);
}

/* the rail says which kind of state without a second badge */
.gas-row__rail {
  position: absolute;
  top: 0;
  bottom: 0;
  left: 0;
  width: 3px;
}

.gas-row--pending .gas-row__rail  { background: $a-warn; }
.gas-row--active .gas-row__rail   { background: $a-blue; }
.gas-row--done .gas-row__rail     { background: $a-good; }
.gas-row--declined .gas-row__rail { background: rgba(10, 37, 64, 0.16); }

.gas-row__body {
  display: grid;
  grid-template-columns: 190px minmax(0, 1fr) 250px 130px 128px;
  align-items: center;
  gap: 22px;
  padding: 20px 22px 20px 25px;
}

.gas-cell { min-width: 0; }

.gas-page .gas-cell__label {
  margin: 0 0 5px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gas-page .gas-ref {
  margin: 0;
  font-size: 15px;
  font-weight: 600;
  letter-spacing: -0.012em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gas-page .gas-when {
  margin: 5px 0 0;
  font-size: 12.5px;
  color: $a-ink-4;
}

.gas-page .gas-prog {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.45;
  letter-spacing: -0.008em;
  color: $a-navy;
}

/* said rather than left blank, so nobody wonders whether it
   failed to load */
.gas-page .gas-prog.is-blank {
  font-weight: 400;
  font-style: italic;
  color: $a-ink-4;
}

.gas-page .gas-prog__num {
  margin: 4px 0 0;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}


/* ---------- the state and the bar ----------

   The bar is the analytic on each row: how far through the nine
   stages this application has got, which is the only question
   anybody opens this page to ask.
   ------------------------------------------------------- */

.gas-stage {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 14px;
  margin-bottom: 9px;
}

.gas-state {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  white-space: nowrap;
}

.gas-state__dot {
  width: 7px;
  height: 7px;
  border-radius: 50%;
  flex-shrink: 0;
}

.gas-state--pending  { color: $a-warn; }
.gas-state--active   { color: $a-blue-dk; }
.gas-state--done     { color: $a-good; }
.gas-state--declined { color: $a-ink-4; }

.gas-state--pending .gas-state__dot { background: $a-warn; }
.gas-state--active .gas-state__dot  { background: $a-blue; }
.gas-state--done .gas-state__dot    { background: $a-good; }
.gas-state--declined .gas-state__dot {
  background: transparent;
  box-shadow: inset 0 0 0 1.5px rgba(10, 37, 64, 0.28);
}

.gas-stage__pct {
  font-size: 13px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  color: $a-ink-3;
}

.gas-bar {
  display: block;
  height: 8px;
  border-radius: 999px;
  background: $a-tint;
  box-shadow: inset 0 0 0 1px $a-line-2;
  overflow: hidden;
}

.gas-bar__fill {
  display: block;
  height: 100%;
  border-radius: 999px;
  transform-origin: left center;
}

.gas-bar__fill--pending  { background: rgba(164, 116, 31, 0.55); }
.gas-bar__fill--active   { background: rgba(21, 96, 224, 0.60); }
.gas-bar__fill--done     { background: rgba(31, 138, 99, 0.60); }
.gas-bar__fill--declined { background: rgba(10, 37, 64, 0.20); }

.gas-page .gas-stage__note {
  margin: 8px 0 0;
  font-size: 12px;
  color: $a-ink-4;
}

.gas-page .gas-moved {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gas-cell--acts {
  display: flex;
  align-items: center;
  justify-content: flex-end;
  gap: 8px;
}


/* =========================================================
   THE TIMELINE

   Vertical, not horizontal. Nine stages across a row gives each
   about ninety pixels, which is not enough for a label and a
   date — they end up rotated or truncated, and a rotated label
   is one nobody reads. Down the page each stage gets a full
   line and its date sits beside it.
   ========================================================= */

.gas-tl {
  padding: 22px 25px 26px;
  border-top: 1px solid $a-line-2;
  background: $a-tint;
}

.gas-page .gas-tl__label {
  margin: 0 0 18px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $a-blue;
}

.gas-page .gas-tl__list {
  margin: 0;
  padding: 0;
  list-style: none;
}

.gas-tl__step {
  position: relative;
  display: flex;
  align-items: flex-start;
  gap: 16px;
  padding-bottom: 20px;
}

.gas-tl__step:last-child { padding-bottom: 0; }

/* the connector runs from the dot downward, so the last step
   has nothing hanging off the bottom of it */
.gas-tl__step::before {
  content: "";
  position: absolute;
  top: 24px;
  bottom: 0;
  left: 11px;
  width: 2px;
  background: $a-line;
}

.gas-tl__step:last-child::before { display: none; }

.gas-tl__step.is-done::before { background: rgba(21, 96, 224, 0.30); }

.gas-tl__dot {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  border-radius: 50%;
  background: $a-white;
  box-shadow: inset 0 0 0 2px $a-line;
  font-size: 10px;
  color: $a-ink-4;
  z-index: 1;
}

.gas-tl__step.is-done .gas-tl__dot {
  background: $a-blue-1;
  box-shadow: inset 0 0 0 2px rgba(21, 96, 224, 0.35);
  color: $a-blue-dk;
}

/* the current step is the only ring filled solid, so the eye
   lands on it before it reads anything */
.gas-tl__step.is-now .gas-tl__dot {
  background: $a-blue;
  box-shadow: 0 0 0 4px $a-blue-1;
  color: $a-white;
}

.gas-tl__step.is-stop .gas-tl__dot {
  background: $a-stop-1;
  box-shadow: inset 0 0 0 2px rgba(184, 57, 74, 0.32);
  color: $a-stop;
}

.gas-tl__body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  padding-top: 2px;
  min-width: 0;
}

.gas-tl__name {
  font-size: 14px;
  font-weight: 500;
  letter-spacing: -0.008em;
  color: $a-ink-3;
}

.gas-tl__step.is-done .gas-tl__name { color: $a-ink-2; }

.gas-tl__step.is-now .gas-tl__name {
  font-weight: 600;
  color: $a-navy;
}

.gas-tl__step.is-stop .gas-tl__name {
  font-weight: 600;
  color: $a-stop;
}

.gas-tl__date {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: $a-ink-4;
}

.gas-tl__date.is-next {
  font-style: italic;
  color: rgba(10, 37, 64, 0.30);
}


/* =========================================================
   PAGER

   Ten to a page. The count on the left says which ten, because
   a row of page numbers on its own does not tell somebody
   whether they are looking at three results or three hundred.
   ========================================================= */

.gas-pager {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 14px 24px;
  padding: 16px 4px 0;
}

.gas-page .gas-pager__count {
  margin: 0;
  font-size: 13px;
  font-variant-numeric: tabular-nums;
  color: $a-ink-4;
}

.gas-pager__ctrl {
  display: flex;
  align-items: center;
  gap: 5px;
}

.gas-page .gas-page {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 36px;
  height: 36px;
  padding: 0 10px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 500;
  font-variant-numeric: tabular-nums;
  color: $a-ink-2;
  cursor: pointer;
  transition: background 0.35s $a-ease, border-color 0.35s $a-ease, color 0.35s $a-ease;
}

.gas-page .gas-page:hover {
  background: $a-white;
  border-color: $a-line;
  color: $a-navy;
}

.gas-page .gas-page.is-on {
  background: $a-blue;
  border-color: $a-blue;
  color: $a-white;
  font-weight: 600;
}

.gas-page .gas-page.is-on:hover {
  background: $a-blue-dk;
  border-color: $a-blue-dk;
  color: $a-white;
}

/* the ellipsis is not a button, so it does not behave like one */
.gas-page .gas-page.is-gap {
  min-width: 22px;
  padding: 0;
  color: $a-ink-4;
  cursor: default;
  background: transparent;
  border-color: transparent;
}

.gas-page .gas-page:disabled {
  opacity: 0.35;
  cursor: default;
  background: transparent;
  border-color: transparent;
}

.gas-page .gas-page--step { color: $a-ink-3; }


/* =========================================================
   EMPTY STATES
   ========================================================= */

.gas-blank {
  max-width: 520px;
  margin: 56px auto;
  padding: 48px 34px 44px;
  border: 1px solid $a-line;
  border-radius: 18px;
  background: $a-white;
  text-align: center;
}

.gas-blank__mark {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 58px;
  height: 58px;
  margin: 0 auto 20px;
  border-radius: 50%;
  background: $a-blue-1;
  color: $a-blue;
  font-size: 22px;
}

.gas-page .gas-blank__title {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  letter-spacing: -0.024em;
  color: $a-navy;
}

.gas-page .gas-blank__text {
  max-width: 44ch;
  margin: 11px auto 22px;
  font-size: 15px;
  line-height: 1.64;
  color: $a-ink-3;
}

.gas-page .gas-empty {
  margin: 0;
  padding: 44px 0;
  text-align: center;
  font-size: 14.5px;
  color: $a-ink-4;
}


/* =========================================================
   THE DETAIL PANEL
   ========================================================= */

.gas-veil {
  position: fixed;
  top: 0;
  right: 0;
  bottom: 0;
  left: 0;
  z-index: 1050;
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 40px 20px;
  background: rgba(10, 37, 64, 0.44);
  backdrop-filter: blur(3px);
}

.gas-modal {
  display: flex;
  flex-direction: column;
  width: 100%;
  max-width: 860px;
  max-height: 100%;
  border-radius: 18px;
  background: $a-white;
  overflow: hidden;
  box-shadow: 0 30px 70px rgba(10, 37, 64, 0.26);
}

.gas-modal__head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 24px 20px;
  border-bottom: 1px solid $a-line-2;
}

.gas-page .gas-modal__ref {
  margin: 0;
  font-size: 21px;
  font-weight: 700;
  letter-spacing: -0.024em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
}

.gas-page .gas-modal__sub {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 10px;
  margin: 9px 0 0;
  font-size: 12.5px;
  color: $a-ink-4;
}

.gas-modal__sep { color: rgba(10, 37, 64, 0.22); }

.gas-tabs--modal {
  padding: 12px 16px;
  border-bottom: 1px solid $a-line-2;
  background: rgba(10, 37, 64, 0.02);
  flex-wrap: nowrap;
  overflow-x: auto;
  -webkit-overflow-scrolling: touch;
}

.gas-modal__body {
  flex: 1;
  padding: 24px 26px 28px;
  overflow-y: auto;
}

.gas-modal__foot {
  display: flex;
  justify-content: flex-end;
  padding: 16px 24px;
  border-top: 1px solid $a-line-2;
  background: $a-tint;
}

.gas-page .gas-sub {
  margin: 0 0 16px;
  font-size: 11px;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: $a-blue;
}

.gas-page .gas-kvs + .gas-sub {
  margin-top: 30px;
  padding-top: 26px;
  border-top: 1px solid $a-line-2;
}

.gas-page .gas-kvs {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 16px 30px;
  margin: 0;
  padding: 0;
}

.gas-kv { min-width: 0; }

.gas-page .gas-kv dt {
  margin: 0 0 5px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

.gas-page .gas-kv dd {
  margin: 0;
  font-size: 14px;
  font-weight: 600;
  line-height: 1.5;
  letter-spacing: -0.008em;
  font-variant-numeric: tabular-nums;
  color: $a-navy;
  word-break: break-word;
}

.gas-page .gas-kv dd.is-blank {
  font-weight: 400;
  font-style: italic;
  font-variant-numeric: normal;
  color: $a-ink-4;
}

.gas-prose { margin-top: 26px; }

.gas-page .gas-prose__label {
  margin: 0 0 7px;
  font-size: 10.5px;
  font-weight: 600;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: $a-ink-4;
}

/* the line breaks the author typed are kept */
.gas-page .gas-prose__text {
  margin: 0;
  max-width: 76ch;
  font-size: 15px;
  line-height: 1.7;
  color: $a-ink-2;
  white-space: pre-line;
}


/* ---------- attachments ---------- */

.gas-files {
  display: grid;
  gap: 8px;
}

.gas-file {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 13px 16px;
  border: 1px solid $a-line;
  border-radius: 12px;
  background: $a-white;
  transition: border-color 0.4s $a-ease, background 0.4s $a-ease;
}

.gas-file:hover {
  border-color: $a-blue-2;
  background: $a-blue-1;
}

.gas-file__ico {
  display: flex;
  align-items: center;
  justify-content: center;
  width: 36px;
  height: 36px;
  flex-shrink: 0;
  border-radius: 10px;
  background: $a-tint;
  color: $a-ink-3;
  font-size: 15px;
}

.gas-file__body {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 1;
  min-width: 0;
}

.gas-file__name {
  font-size: 14px;
  font-weight: 500;
  color: $a-navy;
  word-break: break-word;
}

.gas-file__size {
  font-size: 12px;
  font-variant-numeric: tabular-nums;
  color: $a-ink-4;
}


/* =========================================================
   CONTROLS
   ========================================================= */

.gas-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  height: 40px;
  padding: 0 17px;
  border: 1px solid transparent;
  border-radius: 10px;
  background: transparent;
  font-family: inherit;
  font-size: 13.5px;
  font-weight: 600;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  transition: background 0.4s $a-ease, border-color 0.4s $a-ease, color 0.4s $a-ease;
}

.gas-btn--sm {
  height: 34px;
  padding: 0 13px;
  font-size: 13px;
}

.gas-btn--ghost {
  border-color: $a-line;
  color: $a-ink-2;
}

.gas-btn--ghost:hover,
.gas-btn--ghost:focus {
  border-color: $a-blue-2;
  color: $a-blue-dk;
  text-decoration: none;
}

.gas-icon {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 34px;
  height: 34px;
  padding: 0;
  border: 1px solid $a-line;
  border-radius: 10px;
  background: $a-white;
  color: $a-ink-3;
  cursor: pointer;
  transition: background 0.4s $a-ease, border-color 0.4s $a-ease,
              color 0.4s $a-ease, transform 0.4s $a-ease;
}

.gas-icon:hover {
  border-color: $a-blue-2;
  color: $a-blue-dk;
}

/* the chevron turns to point at the panel it opened */
.gas-icon.is-on {
  background: $a-blue-1;
  border-color: $a-blue-2;
  color: $a-blue-dk;
  transform: rotate(180deg);
}

.gas-btn:focus-visible,
.gas-tab:focus-visible,
.gas-icon:focus-visible,
.gas-back:focus-visible,
.gas-page .gas-page:focus-visible {
  outline: 2px solid $a-blue;
  outline-offset: 2px;
}


/* =========================================================
   MOTION

   Everything settles once, in one direction, on one easing.
   The rows stagger so the eye follows the list downward rather
   than the whole page appearing at once.
   ========================================================= */

@media (prefers-reduced-motion: no-preference) {

  @keyframes gasRise {
    from { opacity: 0; transform: translateY(14px); }
    to   { opacity: 1; transform: translateY(0); }
  }

  @keyframes gasDrawX {
    from { transform: scaleX(0); }
    to   { transform: scaleX(1); }
  }

  @keyframes gasFade {
    from { opacity: 0; }
    to   { opacity: 1; }
  }

  @keyframes gasPop {
    from { opacity: 0; transform: translateY(18px) scale(0.985); }
    to   { opacity: 1; transform: translateY(0) scale(1); }
  }

  @keyframes gasSlide {
    from { opacity: 0; transform: translateX(-10px); }
    to   { opacity: 1; transform: translateX(0); }
  }

  .gas-top     { animation: gasRise 0.6s $a-ease backwards; }
  .gas-sum     { animation: gasRise 0.6s $a-ease 0.08s backwards; }
  .gas-filters { animation: gasRise 0.6s $a-ease 0.18s backwards; }
  .gas-blank   { animation: gasRise 0.6s $a-ease 0.1s backwards; }
  .gas-pager   { animation: gasFade 0.5s $a-ease 0.6s backwards; }

  .gas-spread__seg { animation: gasDrawX 0.85s $a-ease 0.3s backwards; }
  .gas-bar__fill   { animation: gasDrawX 0.9s $a-ease 0.42s backwards; }

  /* ten rows to a page, so the stagger is tuned to exactly ten
     and the last one still lands inside a second */
  .gas-row { animation: gasRise 0.5s $a-ease backwards; }

  .gas-row:nth-child(1)  { animation-delay: 0.26s; }
  .gas-row:nth-child(2)  { animation-delay: 0.31s; }
  .gas-row:nth-child(3)  { animation-delay: 0.36s; }
  .gas-row:nth-child(4)  { animation-delay: 0.41s; }
  .gas-row:nth-child(5)  { animation-delay: 0.46s; }
  .gas-row:nth-child(6)  { animation-delay: 0.51s; }
  .gas-row:nth-child(7)  { animation-delay: 0.56s; }
  .gas-row:nth-child(8)  { animation-delay: 0.61s; }
  .gas-row:nth-child(9)  { animation-delay: 0.66s; }
  .gas-row:nth-child(10) { animation-delay: 0.71s; }

  .gas-tl { animation: gasFade 0.4s $a-ease backwards; }

  .gas-tl__step { animation: gasSlide 0.4s $a-ease backwards; }

  .gas-tl__step:nth-child(1) { animation-delay: 0.04s; }
  .gas-tl__step:nth-child(2) { animation-delay: 0.08s; }
  .gas-tl__step:nth-child(3) { animation-delay: 0.12s; }
  .gas-tl__step:nth-child(4) { animation-delay: 0.16s; }
  .gas-tl__step:nth-child(5) { animation-delay: 0.20s; }
  .gas-tl__step:nth-child(n+6) { animation-delay: 0.24s; }

  .gas-veil  { animation: gasFade 0.25s $a-ease; }
  .gas-modal { animation: gasPop 0.4s $a-ease; }
}


/* =========================================================
   RESPONSIVE
   ========================================================= */

@media (max-width: 1180px) {

  .gas-page { padding: 32px 20px 80px; }

  /* the bar keeps its width and the programme column gives
     ground, because a squeezed progress bar stops being
     readable before a wrapped programme name does */
  .gas-row__body {
    grid-template-columns: 170px minmax(0, 1fr) 220px 120px;
    gap: 18px;
  }

  .gas-cell--acts {
    grid-column: 1 / -1;
    justify-content: flex-start;
    padding-top: 6px;
    margin-top: 2px;
    border-top: 1px solid $a-line-2;
  }

  .gas-page .gas-kvs { grid-template-columns: repeat(2, minmax(0, 1fr)); }
}

@media (max-width: 900px) {

  .gas-sum__head { gap: 18px; }

  .gas-page .gas-stats { width: 100%; }

  .gas-stat {
    flex: 1;
    padding: 2px 14px;
  }

  .gas-row__body {
    grid-template-columns: minmax(0, 1fr) minmax(0, 1fr);
    gap: 16px 20px;
  }

  /* the reference is the row's heading and the bar is what the
     reader came for, so both take the full width */
  .gas-cell--ref   { grid-column: 1 / -1; }
  .gas-cell--track { grid-column: 1 / -1; }
  .gas-cell--prog  { grid-column: 1 / 2; }

  .gas-cell--moved { text-align: right; }
}

@media (max-width: 640px) {

  .gas-page { padding: 24px 14px 64px; }

  .gas-page .gas-top__title { font-size: 22px; }

  .gas-sum { padding: 20px 18px 22px; }

  .gas-page .gas-sum__figure { font-size: 30px; }

  .gas-stat {
    padding: 2px 10px;
    flex: 1 1 40%;
  }

  .gas-filters {
    align-items: stretch;
    flex-direction: column;
  }

  .gas-search { width: 100%; }

  .gas-tabs {
    flex-wrap: nowrap;
    overflow-x: auto;
    -webkit-overflow-scrolling: touch;
    padding-bottom: 2px;
  }

  .gas-row__body {
    grid-template-columns: minmax(0, 1fr);
    gap: 15px;
    padding: 18px 16px 18px 19px;
  }

  .gas-cell--moved { text-align: left; }

  .gas-cell--acts {
    justify-content: space-between;
    width: 100%;
  }

  .gas-pager {
    align-items: flex-start;
    flex-direction: column;
    gap: 12px;
  }

  .gas-page .gas-kvs { grid-template-columns: minmax(0, 1fr); }

  .gas-tl { padding: 20px 16px 22px 19px; }

  .gas-veil { padding: 0; }

  .gas-modal {
    max-width: none;
    height: 100%;
    max-height: none;
    border-radius: 0;
  }

  .gas-modal__body { padding: 20px 16px 24px; }
}

@media (prefers-reduced-motion: reduce) {
  .gas-page * { transition: none; }
  .gas-icon.is-on { transform: none; }
}

sp_widget.script:
(function () {

  /* =========================================================
     GATENOW · APPLICATION STATUS
     Service Portal widget · Server script

     A standalone tracking page. Every application belonging to
     the current user, with a derived position in the process so
     the page can say how far along each one is rather than only
     naming its state.

     There is no rail and no dashboard chrome here — this script
     publishes a list and one summary, nothing else.

     WHAT CHANGED FROM THE PREVIOUS VERSION

     1. The eleven-colour map is gone. Colour now names a kind
        of state — waiting, moving, finished, stopped — and the
        state's own label carries the detail. Eleven hues
        carried nothing, because nobody memorises eleven hues.

     2. Timeline steps now carry real dates. The old template
        bound step.date and the old server never set it, so
        every step read "Upcoming" no matter what had happened.

     3. Each application gets pct and stageNote, so the list can
        show progress rather than only a badge.

     4. The back link is a page id. The old one hardcoded a full
        instance hostname, which breaks on the first clone.
     ========================================================= */

  var APPLICANT = 'x_enno_gatenow_service_applicants';

  var me = gs.getUserName();
  if (!me) return;

  data.applications = [];
  data.timelines    = {};

  function opt(name, fallback) {
    var v = options[name];
    return (v === null || v === undefined || v === '') ? fallback : v.toString();
  }
data.backUrl = '/applicant';

data.pageSize = parseInt(opt('page_size', '10'), 10) || 10;




  /* ============================================================
     HELPERS
     ============================================================ */

  var MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
                'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];

  function fmtDate(raw) {
    if (!raw || raw === 'null') return '';
    var day = String(raw).split(' ')[0].split('-');
    if (day.length !== 3) return String(raw).split(' ')[0];
    return parseInt(day[2], 10) + ' ' + MONTHS[parseInt(day[1], 10) - 1] + ' ' + day[0];
  }

  function commas(n) {
    var s = '' + Math.round(n);
    var out = '';
    var c = 0;
    for (var i = s.length - 1; i >= 0; i--) {
      out = s.charAt(i) + out;
      c++;
      if (c % 3 === 0 && i > 0) out = ',' + out;
    }
    return out;
  }

  function money(raw) {
    var n = parseFloat(raw);
    if (isNaN(n) || n <= 0) return '';
    if (n >= 1000000) return '$' + (n / 1000000).toFixed(1).replace(/\.0$/, '') + 'M';
    if (n >= 1000)    return '$' + Math.round(n / 1000) + 'K';
    return '$' + commas(n);
  }

  /* names that are not on every version of a table are read
     through pick(), which skips the ones that do not exist */
  function pick(gr, names) {
    for (var i = 0; i < names.length; i++) {
      try {
        if (gr.isValidField(names[i])) {
          var v = gr.getValue(names[i]);
          if (v !== null && v !== undefined && v !== '') return v;
        }
      } catch (e) { /* next */ }
    }
    return '';
  }


  /* ============================================================
     THE PROCESS

     Nine stages in order, plus two ways of leaving it. The order
     is what makes a percentage mean anything — without it, a
     state is just a word.
     ============================================================ */

  var ORDER = [
    'new', 'ready_for_review', 'review_in_progress', 'review_completed',
    'award_pending', 'award_acknowledged', 'project_in_progress',
    'project_completed', 'closed'
  ];

  var LABELS = {
    'new'                  : gs.getMessage('Application created'),
    'ready_for_review'     : gs.getMessage('Ready for review'),
    'review_in_progress'   : gs.getMessage('Review in progress'),
    'review_completed'     : gs.getMessage('Review completed'),
    'award_pending'        : gs.getMessage('Award pending'),
    'award_acknowledged'   : gs.getMessage('Award acknowledged'),
    'project_in_progress'  : gs.getMessage('Project in progress'),
    'project_completed'    : gs.getMessage('Project completed'),
    'closed'               : gs.getMessage('Closed'),
    'declined_by_agency'   : gs.getMessage('Declined by agency'),
    'declined_by_applicant': gs.getMessage('Declined by applicant')
  };

  /* Four tones, not eleven colours.

     pending  — waiting on somebody to act
     active   — moving through the process
     done     — finished
     declined — stopped

     A tone is a category. The state's label says which
     particular state it is. */
  var TONES = {
    'new'                  : 'pending',
    'ready_for_review'     : 'pending',
    'review_in_progress'   : 'active',
    'review_completed'     : 'active',
    'award_pending'        : 'pending',
    'award_acknowledged'   : 'active',
    'project_in_progress'  : 'active',
    'project_completed'    : 'done',
    'closed'               : 'done',
    'declined_by_agency'   : 'declined',
    'declined_by_applicant': 'declined'
  };

  function stopped(state) {
    return state === 'declined_by_agency' || state === 'declined_by_applicant';
  }


  /* ============================================================
     STATE HISTORY

     One query per application against sys_history_line, giving
     the date each state was entered. The old template bound
     step.date but nothing populated it, so the timeline showed
     no dates at all.

     Mapped back from the display label, because the label is
     what the history table stores.
     ============================================================ */

  var BY_LABEL = {};
  for (var lk in LABELS) {
    if (LABELS.hasOwnProperty(lk)) BY_LABEL[LABELS[lk]] = lk;
  }

  function historyDates(sysId) {

    var dates = {};

    try {
      var h = new GlideRecordSecure('sys_history_line');
      h.addQuery('set.id', sysId);
      h.addQuery('field', 'state');
      h.orderBy('sys_created_on');
      h.setLimit(40);
      h.query();

      while (h.next()) {
        var entered = BY_LABEL[h.getValue('new')];
        /* first entry into a state is the one that counts — a
           record can bounce back into a state it already had */
        if (entered && !dates[entered]) {
          dates[entered] = fmtDate(h.getValue('sys_created_on'));
        }
      }
    } catch (e) {
      gs.info('[AppStatus] history unreadable for ' + sysId + ': ' + e.message);
    }

    return dates;
  }


  /* ============================================================
     READ THE APPLICATIONS
     ============================================================ */

  var counts = { pending: 0, active: 0, done: 0, declined: 0 };

  var gr = new GlideRecordSecure(APPLICANT);
  gr.addQuery('sys_created_by', me);
  gr.orderByDesc('sys_updated_on');
  gr.query();

  while (gr.next()) {

    var sysId    = gr.getUniqueValue();
    var stateVal = gr.getValue('state') || 'new';
    var isStop   = stopped(stateVal);
    var idx      = ORDER.indexOf(stateVal);

    if (idx === -1 && !isStop) idx = 0;

    var tone = TONES[stateVal] || 'pending';
    counts[tone]++;

    /* Progress is stages entered out of stages total. A declined
       application keeps the percentage it had reached rather
       than dropping to zero — it did get that far, and showing
       0% would misrepresent the work done. */
    var reached = isStop ? Math.max(0, idx) : idx;
    var pct = Math.round(((reached + 1) / ORDER.length) * 100);
    if (pct > 100) pct = 100;
    if (pct < 0)   pct = 0;

    var stageNote = isStop
      ? gs.getMessage('Stopped at stage') + ' ' + (reached + 1) + ' ' +
        gs.getMessage('of') + ' ' + ORDER.length
      : gs.getMessage('Stage') + ' ' + (reached + 1) + ' ' + gs.getMessage('of') + ' ' +
        ORDER.length + ' · ' + (ORDER.length - reached - 1) + ' ' + gs.getMessage('remaining');

    /* ---------- attachments ---------- */
    var files = [];

    try {
      var at = new GlideRecordSecure('sys_attachment');
      at.addQuery('table_name', APPLICANT);
      at.addQuery('table_sys_id', sysId);
      at.query();

      while (at.next()) {
        files.push({
          sys_id      : at.getUniqueValue(),
          name        : at.getValue('file_name') || '',
          size        : at.getValue('size_bytes') || '0',
          content_type: at.getValue('content_type') || ''
        });
      }
    } catch (e) {
      gs.info('[AppStatus] attachments unreadable for ' + sysId + ': ' + e.message);
    }

    var programName = gr.getDisplayValue('program.program_name') || '';

    var app = {
      sys_id: sysId,
      number: gr.getValue('number') || '',

      state_value  : stateVal,
      state_display: gr.getDisplayValue('state') || LABELS[stateVal] || stateVal,
      tone         : tone,
      stopped      : isStop,
      pct          : pct,
      stageNote    : stageNote,

      created_on: fmtDate(gr.getValue('sys_created_on')),
      updated_on: fmtDate(gr.getValue('sys_updated_on')),

      hasProgram      : !!programName,
      program_name    : programName,
      program_num     : gr.getDisplayValue('program.number') || '',
      program_category: gr.getDisplayValue('program_category') || '',

      first_name : gr.getValue('first_name')  || '',
      middle_name: gr.getValue('middle_name') || '',
      last_name  : gr.getValue('last_name')   || '',
      birthdate  : fmtDate(gr.getValue('birthdate')),
      phone      : gr.getValue('phone_number') || '',
      email      : gr.getValue('email') || '',

      gender_display   : gr.getDisplayValue('gender') || '',
      marital_display  : gr.getDisplayValue('marital_status') || '',
      race_display     : gr.getDisplayValue('race') || '',
      ethnicity_display: gr.getDisplayValue('ethnicity') || '',
      education_display: gr.getDisplayValue('education_level') || '',
      military_display : gr.getDisplayValue('military_status') || '',

      street : gr.getValue('street') || '',
      city   : gr.getValue('city') || '',
      zip    : gr.getValue('zip_postal_code') || '',
      country: gr.getValue('country') || '',

      applicant_type_display: gr.getDisplayValue('applicant_type') || '',
      citizenship_display   : gr.getDisplayValue('citizenship_status') || '',
      identity_display      : gr.getDisplayValue('identity_type') || '',
      tribal_display        : gr.getDisplayValue('tribal_affiliation') || '',
      disability_display    : gr.getDisplayValue('disability_status') || '',

      uei    : pick(gr, ['uei']),
      tin_ein: pick(gr, ['tin_ein']),
      ssn    : pick(gr, ['ssn']),

      organization    : gr.getValue('organization') || '',
      requested_budget: money(gr.getValue('requested_budget')),
      submission_date : fmtDate(gr.getValue('submission_date')),
      start_date      : fmtDate(gr.getValue('project_start_date')),
      end_date        : fmtDate(gr.getValue('project_end_date')),

      short_description   : gr.getValue('short_description') || '',
      proposal_description: gr.getValue('proposal_description') || '',
      project_goals       : gr.getValue('project_goals_and_objectives') || '',
      project_activities  : gr.getValue('project_activities_methodology') || '',

      attachments: files
    };

    /* one lowercase blob for the search box, assembled once here
       rather than joined per keystroke in the browser */
    app.search = (app.number + ' ' + app.program_name + ' ' +
                  app.state_display + ' ' + app.program_num).toLowerCase();

    data.applications.push(app);


    /* ---------- the timeline ---------- */

    var dates = historyDates(sysId);
    var steps = [];

    for (var n = 0; n < ORDER.length; n++) {

      if (isStop) {
        /* the stage it stopped at is replaced by the decline;
           everything after is left as never reached */
        if (n < reached) {
          steps.push({ state: ORDER[n], label: LABELS[ORDER[n]],
                       date: dates[ORDER[n]] || '', status: 'done' });
        } else if (n === reached) {
          steps.push({ state: stateVal, label: LABELS[stateVal],
                       date: dates[stateVal] || fmtDate(gr.getValue('sys_updated_on')),
                       status: 'stop' });
        } else {
          steps.push({ state: ORDER[n], label: LABELS[ORDER[n]],
                       date: '', status: 'next' });
        }
      } else {
        steps.push({
          state : ORDER[n],
          label : LABELS[ORDER[n]],
          date  : dates[ORDER[n]] || '',
          status: n < idx ? 'done' : (n === idx ? 'now' : 'next')
        });
      }
    }

    data.timelines[sysId] = steps;
  }


  /* ============================================================
     THE SUMMARY

     One object, not a set of tiles. A total, four counts, and
     the share of the list each tone holds.
     ============================================================ */

  var total = data.applications.length;

  function pctOf(n) {
    return total > 0 ? Math.round((n / total) * 100) : 0;
  }

  var rows = [];

  function addRow(key, label) {
    if (!counts[key]) return;
    rows.push({ key: key, label: label, count: counts[key], pct: pctOf(counts[key]) });
  }

  addRow('pending',  gs.getMessage('Waiting'));
  addRow('active',   gs.getMessage('In progress'));
  addRow('done',     gs.getMessage('Completed'));
  addRow('declined', gs.getMessage('Declined'));

  data.summary = {
    total     : total,
    totalLabel: total === 1 ? gs.getMessage('application') : gs.getMessage('applications'),
    rows      : rows,
    stats: [
      { key: 'pending',  label: gs.getMessage('Waiting'),     count: counts.pending,
        alert: counts.pending > 0 },
      { key: 'active',   label: gs.getMessage('In progress'), count: counts.active },
      { key: 'done',     label: gs.getMessage('Completed'),   count: counts.done },
      { key: 'declined', label: gs.getMessage('Declined'),    count: counts.declined }
    ]
  };


  /* ============================================================
     COPY
     ============================================================ */

  data.t = {
    title: gs.getMessage('Application status'),
    sub  : gs.getMessage('Where each of your applications has got to'),
    back : gs.getMessage('Back'),

    searchPlace: gs.getMessage('Search by reference or program'),
    clear      : gs.getMessage('Clear search'),
    reset      : gs.getMessage('Clear filters'),

    fAll     : gs.getMessage('All'),
    fPending : gs.getMessage('Waiting'),
    fActive  : gs.getMessage('In progress'),
    fDone    : gs.getMessage('Completed'),
    fDeclined: gs.getMessage('Declined'),

    program  : gs.getMessage('Program'),
    noProgram: gs.getMessage('Not assigned'),
    submitted: gs.getMessage('Submitted'),
    moved    : gs.getMessage('Last change'),
    progress : gs.getMessage('Application progress'),
    upcoming : gs.getMessage('Not yet reached'),
    view     : gs.getMessage('Details'),

    showing: gs.getMessage('Showing'),
    of     : gs.getMessage('of'),
    prev   : gs.getMessage('Previous page'),
    next   : gs.getMessage('Next page'),

    emptyTitle : gs.getMessage('No applications yet'),
    emptyText  : gs.getMessage('Anything you submit will appear here, with its progress through review.'),
    noMatch    : gs.getMessage('Nothing matches that'),
    noMatchHint: gs.getMessage('Try a different reference, program name or status.'),

    secPersonal: gs.getMessage('Personal information'),
    secAddress : gs.getMessage('Address'),
    secIdentity: gs.getMessage('Identity and classification'),
    secProgram : gs.getMessage('Program and project'),
    secFiles   : gs.getMessage('Attachments'),

    tabPersonal: gs.getMessage('Personal'),
    tabIdentity: gs.getMessage('Identity'),
    tabProgram : gs.getMessage('Program'),
    tabFiles   : gs.getMessage('Attachments'),

    fName : gs.getMessage('First name'),
    mName : gs.getMessage('Middle name'),
    lName : gs.getMessage('Last name'),
    dob   : gs.getMessage('Date of birth'),
    phone : gs.getMessage('Phone'),
    email : gs.getMessage('Email'),
    gender: gs.getMessage('Gender'),
    marital  : gs.getMessage('Marital status'),
    race     : gs.getMessage('Race'),
    ethnicity: gs.getMessage('Ethnicity'),
    education: gs.getMessage('Education level'),
    military : gs.getMessage('Military status'),

    street : gs.getMessage('Street'),
    city   : gs.getMessage('City'),
    zip    : gs.getMessage('Postal code'),
    country: gs.getMessage('Country'),

    appType   : gs.getMessage('Applicant type'),
    citizen   : gs.getMessage('Citizenship status'),
    idType    : gs.getMessage('Identity type'),
    tribal    : gs.getMessage('Tribal affiliation'),
    disability: gs.getMessage('Disability status'),
    uei       : gs.getMessage('UEI'),
    tin       : gs.getMessage('TIN / EIN'),
    ssn       : gs.getMessage('SSN'),

    progName : gs.getMessage('Program name'),
    progNum  : gs.getMessage('Program number'),
    progCat  : gs.getMessage('Category'),
    org      : gs.getMessage('Organisation'),
    budget   : gs.getMessage('Requested budget'),
    projStart: gs.getMessage('Project start'),
    projEnd  : gs.getMessage('Project end'),

    shortDesc : gs.getMessage('Short description'),
    proposal  : gs.getMessage('Proposal'),
    goals     : gs.getMessage('Goals and objectives'),
    activities: gs.getMessage('Activities and methodology'),

    download: gs.getMessage('Download'),
    noFiles : gs.getMessage('No files were attached to this application.'),
    close   : gs.getMessage('Close'),
    none    : gs.getMessage('Not provided')
  };

})();
